{"command":"cat > /tmp/ptytest2.py << 'PY'
import os, time, select, sys, fcntl, termios, struct
def run(extra_args=[], keys=b"q", wait=1.0):
    open("/tmp/ping_lines.txt","w").write("64 bytes from 127.0.0.1: icmp_seq=1 ttl=64 time=12.3 ms\n")
    for f in ["/tmp/ping_finite","/tmp/ping_exit"]:
        try: os.remove(f)
        except: pass
    pid, fd = os.forkpty() if hasattr(os,"forkpty") else (None,None)
    if pid is None:
        import pty; pid, fd = pty.fork()
    if pid==0:
        fcntl.ioctl(0, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
        os.environ["PATH"]="/tmp/fakebin:"+os.environ["PATH"]
        os.environ["TERM"]="xterm-256color"
        os.execv("/workspace/executable", ["/workspace/executable"]+extra_args+["127.0.0.1"])
    data=b""; start=time.time()
    while time.time()-start<wait:
        r,_,_=select.select([fd],[],[],0.1)
        if fd in r:
            try: c=os.read(fd,65536)
            except: break
            if not c: break
            data+=c
    print("ARGS",extra_args,"initial len",len(data))
    print(repr(data))
    if keys: os.write(fd, keys)
    data2=b""; status=None; start=time.time()
    while time.time()-start<2:
        r,_,_=select.select([fd],[],[],0.1)
        if fd in r:
            try: c=os.read(fd,65536)
            except: break
            if not c: break
            data2+=c
        w,st=os.waitpid(pid, os.WNOHANG)
        if w: status=os.waitstatus_to_exitcode(st); break
    print("after key status",status,"data",repr(data2))
    try:
        w,st=os.waitpid(pid, os.WNOHANG)
        print("final wait",w,st if w else "")
    except Exception as e: print(e)

run([])
run(["--clear"])
PY
python3 /tmp/ptytest2.py
