use crate::PingResult;
use std::fmt;
use std::io::{BufRead, BufReader};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::Duration;

fn detect_ping() -> Result<(), Error> {
    let output = Command::new("ping")
        .arg("-V")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .map_err(Error::Spawn)?;
    let stdout = String::from_utf8(output.stdout).expect("Error decoding ping stdout");
    let stderr = String::from_utf8(output.stderr).expect("Error decoding ping stderr");
    if stdout.contains("iputils") {
        Ok(())
    } else {
        Err(Error::CouldNotDetectPing {
            stderr: first_lines(&stderr),
            stdout: first_lines(&stdout),
        })
    }
}

fn first_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let bytes = text.as_bytes();
    let mut start = 0usize;
    let mut index = 0usize;
    while index < bytes.len() && lines.len() < 2 {
        if bytes[index] == b'\n' || bytes[index] == b'\r' {
            lines.push(text[start..index].to_string());
            if bytes[index] == b'\r' && index + 1 < bytes.len() && bytes[index + 1] == b'\n' {
                index += 1;
            }
            index += 1;
            start = index;
        } else {
            index += 1;
        }
    }
    if lines.len() < 2 && start < text.len() {
        lines.push(text[start..].to_string());
    }
    lines
}

#[derive(Debug)]
pub enum Error {
    Spawn(std::io::Error),
    CouldNotDetectPing {
        stderr: Vec<String>,
        stdout: Vec<String>,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Spawn(error) => write!(formatter, "Error spawning ping: {error}"),
            Self::CouldNotDetectPing { stderr, stdout } => write!(
                formatter,
                "Could not detect ping. Stderr: {stderr:?}\nStdout: {stdout:?}"
            ),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Spawn(error) => Some(error),
            Self::CouldNotDetectPing { .. } => None,
        }
    }
}

pub struct Pinger {
    receiver: mpsc::Receiver<PingResult>,
}

impl Pinger {
    pub fn new(
        host: String,
        ipv6: bool,
        interval: Duration,
        interface: Option<String>,
        ping_args: Vec<String>,
    ) -> Result<Self, Error> {
        detect_ping()?;
        let binary = if ipv6 { "ping6" } else { "ping" };
        let mut command = Command::new(binary);
        command.arg("-O");
        command.arg(format!("-i{:.1}", interval.as_secs_f32()));
        if let Some(interface) = interface {
            command.arg("-I").arg(interface);
        }
        for arg in ping_args {
            command.arg(arg);
        }
        command.arg(host);
        command.stdin(Stdio::null());
        command.stdout(Stdio::piped());
        command.stderr(Stdio::null());
        let mut child: Child = command.spawn().map_err(Error::Spawn)?;
        let stdout = child.stdout.take().expect("ping process has no stdout");
        let (sender, receiver) = mpsc::channel::<PingResult>();
        thread::spawn(move || {
            let mut reader = BufReader::new(stdout);
            loop {
                let mut line = String::new();
                match reader.read_line(&mut line) {
                    Ok(0) => break,
                    Ok(_) => {
                        if sender.send(parse_line(&line)).is_err() {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }
            let _ = child.kill();
        });
        Ok(Self { receiver })
    }

    pub fn receiver(&self) -> &mpsc::Receiver<PingResult> {
        &self.receiver
    }
}

fn parse_line(line: &str) -> PingResult {
    if line.starts_with("64 bytes from") {
        if let Some(duration) = parse_duration(line) {
            return PingResult::Pong(duration);
        }
    }
    if line.starts_with("no answer yet") {
        PingResult::Timeout
    } else {
        PingResult::Idle
    }
}

fn parse_duration(line: &str) -> Option<Duration> {
    let lower = line.to_ascii_lowercase();
    let bytes = lower.as_bytes();
    let mut search_from = 0usize;
    while let Some(relative) = lower[search_from..].find("time=") {
        let position = search_from + relative;
        let rest = &line[position + 5..];
        if let Some(duration) = parse_duration_at(rest) {
            return Some(duration);
        }
        search_from = position + 5;
        if search_from >= bytes.len() {
            break;
        }
    }
    None
}

fn parse_duration_at(rest: &str) -> Option<Duration> {
    let bytes = rest.as_bytes();
    let mut index = 0usize;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        index += 1;
    }
    if index == 0 {
        return None;
    }
    let integer_part = &rest[..index];
    // Values whose integer part does not fit into a u64 are ignored, matching
    // the saturation/overflow behaviour observed for enormous replies.
    integer_part.parse::<u64>().ok()?;
    if index < bytes.len() && bytes[index] == b'.' {
        let fraction_start = index + 1;
        let mut fraction_end = fraction_start;
        while fraction_end < bytes.len() && bytes[fraction_end].is_ascii_digit() {
            fraction_end += 1;
        }
        if fraction_end == fraction_start {
            return None;
        }
        index = fraction_end;
    }
    let number = &rest[..index];
    let mut unit_index = index;
    while unit_index < bytes.len() && bytes[unit_index] == b' ' {
        unit_index += 1;
    }
    let unit = rest.get(unit_index..unit_index + 2)?;
    if !unit.eq_ignore_ascii_case("ms") {
        return None;
    }
    let milliseconds: f64 = number.parse().ok()?;
    if !milliseconds.is_finite() || milliseconds > 18_446_744_073_709_551_615.0 {
        return None;
    }
    Some(Duration::from_micros((milliseconds * 1000.0) as u64))
}
