use std::collections::VecDeque;
use std::time::Duration;

#[derive(Debug, Clone, Copy)]
struct Point {
    x: f64,
    duration: Option<Duration>,
}

#[derive(Debug, Clone)]
pub struct Stats {
    pub last: Duration,
    pub min: Duration,
    pub max: Duration,
    pub avg: Duration,
    pub jitter: Duration,
    pub p95: Duration,
    pub timeouts: usize,
}

#[derive(Debug)]
pub struct PlotData {
    points: VecDeque<Point>,
    buffer_seconds: u64,
}

impl PlotData {
    pub fn new(buffer_seconds: u64) -> Self {
        Self {
            points: VecDeque::new(),
            buffer_seconds,
        }
    }

    pub fn add(&mut self, x: f64, duration: Option<Duration>) {
        self.points.push_back(Point { x, duration });
        let cutoff = x - self.buffer_seconds as f64;
        while let Some(front) = self.points.front() {
            if front.x < cutoff {
                self.points.pop_front();
            } else {
                break;
            }
        }
    }

    pub fn chart_points(&self) -> Vec<(f64, f64)> {
        self.points
            .iter()
            .map(|point| {
                (
                    point.x,
                    point
                        .duration
                        .map(|duration| duration.as_secs_f64() * 1000.0)
                        .unwrap_or(0.0),
                )
            })
            .collect()
    }

    fn successful_durations(&self) -> Vec<Duration> {
        self.points.iter().filter_map(|point| point.duration).collect()
    }

    pub fn stats(&self) -> Option<Stats> {
        let mut durations = self.successful_durations();
        if durations.is_empty() {
            return None;
        }
        durations.sort_unstable();
        let count = durations.len();
        let min = durations[0];
        let max = durations[count - 1];
        let total_micros: u128 = durations.iter().map(|duration| duration.as_micros()).sum();
        let avg = Duration::from_micros((total_micros / count as u128) as u64);
        let jitter = if count > 1 {
            let jitter_micros: u128 = durations
                .windows(2)
                .map(|pair| (pair[1] - pair[0]).as_micros())
                .sum::<u128>()
                / (count as u128 - 1);
            Duration::from_micros(jitter_micros as u64)
        } else {
            Duration::ZERO
        };
        let p95_index = (count as f64 * 0.95).round() as usize;
        let p95 = durations.get(p95_index).copied().unwrap_or_default();
        let last = self
            .points
            .back()
            .and_then(|point| point.duration.or(Some(Duration::ZERO)))
            .unwrap_or_default();
        let timeouts = self.points.iter().filter(|point| point.duration.is_none()).count();
        Some(Stats {
            last,
            min,
            max,
            avg,
            jitter,
            p95,
            timeouts,
        })
    }
}
