#[derive(Debug)]
struct Failure {
    message: String,
    cause: Option<String>,
}

impl Failure {
    fn message(message: impl Into<String>) -> Self {
        Self { message: message.into(), cause: None }
    }
    fn with_cause(message: impl Into<String>, cause: impl Into<String>) -> Self {
        Self { message: message.into(), cause: Some(cause.into()) }
    }
}

impl From<io::Error> for Failure {
    fn from(error: io::Error) -> Self {
        Self::message(error.to_string())
    }
}

impl From<pinger::Error> for Failure {
    fn from(error: pinger::Error) -> Self {
        let cause = std::error::Error::source(&error).map(|source| source.to_string());
        Self { message: error.to_string(), cause }
    }
}

struct CommandSpec {
    program: String,
    args: Vec<String>,
    display_name: String,
}

struct Host {
    display_name: String,
    color: Color,
    data: PlotData,
    receiver: Option<mpsc::Receiver<pinger::PingResult>>,
    _pinger: Option<pinger::Pinger>,
    command: Option<CommandSpec>,
}

struct App {
    args: Args,
    hosts: Vec<Host>,
    interval: Duration,
    start_instant: Instant,
    start_epoch_seconds: i64,
}

fn main() {
    let result = run();
    if let Err(error) = result {
        match error.cause {
            Some(cause) => eprintln!("Error: {}\n\nCaused by:\n    {}", error.message, cause),
            None => eprintln!("Error: {}", error.message),
        }
        std::process::exit(1);
    }
}

fn run() -> Result<(), Failure> {
    let args = Args::parse();
    if args.hosts_or_commands.is_empty() {
        return Err(Failure::message("At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments."));
    }
    let requested_colors = parse_colors(&args.color)?;
    let app = App::new(args, requested_colors)?;
    app.run_terminal()
}

fn parse_colors(requested: &[String]) -> Result<Vec<Color>, Failure> {
    let mut colors = Vec::new();
    for name in requested {
        let color = Color::from_str(name).map_err(|error| {
            Failure::with_cause(format!("Invalid color code: `{name}`"), error.to_string())
        })?;
        colors.push(color);
    }
    Ok(colors)
}

fn color_for_host(index: usize, requested: &[Color], default_index: &mut u8) -> Color {
    if let Some(color) = requested.get(index) {
        *color
    } else {
        let color = Color::Indexed(*default_index);
        *default_index = default_index.wrapping_add(1);
        color
    }
}

fn resolve_host(host: &str, ipv4: bool, ipv6: bool) -> Result<IpAddr, Failure> {
    let addresses: Vec<std::net::SocketAddr> = (host, 0)
        .to_socket_addrs()
        .map_err(|error| Failure::with_cause(format!("Resolving {host}"), error.to_string()))?
        .collect();
    if ipv4 {
        addresses.iter().map(|address| address.ip()).find(|ip| ip.is_ipv4())
            .ok_or_else(|| Failure::message(format!("Could not resolve '{host}' to IPv4")))
    } else if ipv6 {
        addresses.iter().map(|address| address.ip()).find(|ip| ip.is_ipv6())
            .ok_or_else(|| Failure::message(format!("Could not resolve '{host}' to IPv6")))
    } else {
        addresses.first().map(|address| address.ip())
            .ok_or_else(|| Failure::message(format!("Could not resolve '{host}'")))
    }
}

fn expanded_host(input: &str) -> String {
    if let Some(region) = input.strip_prefix("aws:") {
        format!("ec2.{region}.amazonaws.com")
    } else {
        input.to_string()
    }
}

impl App {
    fn new(args: Args, requested_colors: Vec<Color>) -> Result<Self, Failure> {
        let interval_seconds = args.watch_interval.unwrap_or(if args.cmd { 0.5 } else { 0.2 });
        let interval = Duration::from_millis((interval_seconds * 1000.0) as u64);
        let mut hosts: Vec<Host> = Vec::new();
        let mut default_color: u8 = 2;
        if args.cmd {
            let mut commands: Vec<CommandSpec> = Vec::new();
            for command_text in &args.hosts_or_commands {
                let mut pieces = command_text.split_whitespace();
                let program = pieces.next().expect("Must specify a command to watch");
                commands.push(CommandSpec {
                    program: program.to_string(),
                    args: pieces.map(|piece| piece.to_string()).collect(),
                    display_name: command_text.clone(),
                });
            }
            for (index, command) in commands.into_iter().enumerate() {
                let color = color_for_host(index, &requested_colors, &mut default_color);
                hosts.push(Host {
                    display_name: command.display_name.clone(),
                    color,
                    data: PlotData::new(args.buffer),
                    receiver: None,
                    _pinger: None,
                    command: Some(command),
                });
            }
        } else {
            let ping_args = args.ping_args.clone().unwrap_or_default();
            for (index, original) in args.hosts_or_commands.iter().enumerate() {
                let target = expanded_host(original);
                let ip = resolve_host(&target, args.ipv4, args.ipv6)?;
                let display_name = format!("{target} ({ip})");
                let use_ipv6 = args.ipv6
                    || target.parse::<IpAddr>().map(|ip| ip.is_ipv6()).unwrap_or(false);
                let pinger = pinger::Pinger::new(
                    target,
                    use_ipv6,
                    interval,
                    args.interface.clone(),
                    ping_args.clone(),
                )?;
                let color = color_for_host(index, &requested_colors, &mut default_color);
                hosts.push(Host {
                    display_name,
                    color,
                    data: PlotData::new(args.buffer),
                    receiver: None,
                    _pinger: Some(pinger),
                    command: None,
                });
            }
        }
        Ok(Self {
            start_instant: Instant::now(),
            start_epoch_seconds: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|duration| duration.as_secs() as i64)
                .unwrap_or(0),
            args,
            hosts,
            interval,
        })
    }

    fn start_watchers(&mut self) {
        for host in &mut self.hosts {
            if let Some(pinger) = &host._pinger {
                // Ping receivers are already live (the process is spawned when
                // the pinger is constructed). Give each host its receiver by
                // cloning channel endpoints is not possible, so receivers for
                // pings are accessed directly in the receive loop below.
                let _ = pinger;
            }
            if let Some(spec) = &host.command {
                let (sender, receiver) = mpsc::channel();
                let program = spec.program.clone();
                let arguments = spec.args.clone();
                let interval = self.interval;
                std::thread::spawn(move || loop {
                    let start = Instant::now();
                    let result = match Command::new(&program).args(&arguments).output() {
                        Ok(output) if output.status.success() => pinger::PingResult::Pong(start.elapsed()),
                        Ok(_) => pinger::PingResult::Timeout,
                        Err(_) => pinger::PingResult::Idle,
                    };
                    if sender.send(result).is_err() {
                        return;
                    }
                    std::thread::sleep(interval);
                });
                host.receiver = Some(receiver);
            }
        }
    }
}
