fn format_duration(duration: Duration) -> String {
    format!("{:?}", Duration::from_micros(duration.as_micros() as u64))
}

struct FrameData {
    datasets: Vec<Vec<(f64, f64)>>,
    stats: Vec<Option<plot_data::Stats>>,
    x_bounds: [f64; 2],
    x_labels: Vec<String>,
    y_bounds: [f64; 2],
    y_labels: Vec<String>,
}

impl App {
    fn prepare_frame(&self) -> FrameData {
        let datasets: Vec<Vec<(f64, f64)>> = self
            .hosts
            .iter()
            .map(|host| host.data.chart_points())
            .collect();
        let stats: Vec<Option<plot_data::Stats>> = self
            .hosts
            .iter()
            .map(|host| host.data.stats())
            .collect();

        let mut minimum: Option<Duration> = None;
        let mut maximum: Option<Duration> = None;
        for stat in stats.iter().flatten() {
            minimum = Some(minimum.map_or(stat.min, |value: Duration| value.min(stat.min)));
            maximum = Some(maximum.map_or(stat.max, |value: Duration| value.max(stat.max)));
        }
        let (y_bounds, y_labels) = match (minimum, maximum) {
            (Some(min_duration), Some(max_duration)) => {
                let min_micros = min_duration.as_micros() as u64;
                let max_micros = max_duration.as_micros() as u64;
                let low_micros = (min_micros as f64 * 0.9) as u64;
                let high_micros = (max_micros as f64 * 1.1) as u64;
                let step_micros = high_micros.saturating_sub(low_micros) / 7;
                let labels = (0..7)
                    .map(|index| {
                        format_duration(Duration::from_micros(
                            low_micros + step_micros * index,
                        ))
                    })
                    .collect();
                (
                    [
                        min_micros as f64 / 1000.0 * 0.9,
                        max_micros as f64 / 1000.0 * 1.1,
                    ],
                    labels,
                )
            }
            _ => ([0.0, 0.0], (0..7).map(|_| "0ns".to_string()).collect()),
        };

        let elapsed_seconds = self.start_instant.elapsed().as_secs();
        let low_seconds = elapsed_seconds.saturating_sub(self.args.buffer);
        let high_seconds = std::cmp::max(self.args.buffer, elapsed_seconds);
        let base_time = Local
            .timestamp_opt(self.start_epoch_seconds, 0)
            .single()
            .unwrap_or_else(Local::now);
        let x_labels = [low_seconds as f64, (low_seconds as f64 + high_seconds as f64) / 2.0, high_seconds as f64]
            .iter()
            .map(|offset| {
                let time = base_time + chrono::Duration::milliseconds((offset * 1000.0) as i64);
                format!("{}", time.format("%H:%M:%S%.f"))
            })
            .collect();

        FrameData {
            datasets,
            stats,
            x_bounds: [low_seconds as f64, high_seconds as f64],
            x_labels,
            y_bounds,
            y_labels,
        }
    }

    fn run_terminal(mut self) -> Result<(), Failure> {
        terminal::enable_raw_mode()?;
        let backend = CrosstermBackend::new(io::stdout());
        let mut terminal = Terminal::new(backend)?;
        let size = terminal::size()?;
        execute!(io::stdout(), SetSize(size.0, size.1))?;
        if self.args.clear {
            execute!(io::stdout(), EnterAlternateScreen)?;
        }
        terminal.clear()?;
        self.start_watchers();

        let loop_result = self.run_loop(&mut terminal);

        let _ = terminal::disable_raw_mode();
        let _ = terminal.show_cursor();
        if let Ok(current_size) = terminal::size() {
            let _ = execute!(io::stdout(), MoveTo(current_size.0, current_size.1));
        }
        if self.args.clear {
            let _ = execute!(io::stdout(), LeaveAlternateScreen);
        }
        let _ = io::stdout().flush();
        loop_result
    }

    fn run_loop(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    ) -> Result<(), Failure> {
        loop {
            std::thread::sleep(Duration::from_millis(250));

            let mut quit = false;
            while event::poll(Duration::ZERO)? {
                if let Event::Key(key) = event::read()? {
                    match key.code {
                        KeyCode::Char('q') => quit = true,
                        KeyCode::Esc => quit = true,
                        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            quit = true;
                        }
                        _ => {}
                    }
                }
            }
            if quit {
                break;
            }

            let mut disconnected = false;
            let elapsed = self.start_instant.elapsed().as_secs_f64();
            for host in &mut self.hosts {
                if let Some(receiver) = &host.receiver {
                    loop {
                        match receiver.try_recv() {
                            Ok(pinger::PingResult::Pong(duration)) => {
                                host.data.add(elapsed, Some(duration));
                            }
                            Ok(pinger::PingResult::Timeout) => {
                                host.data.add(elapsed, None);
                            }
                            Ok(pinger::PingResult::Idle) => {}
                            Err(mpsc::TryRecvError::Empty) => break,
                            Err(mpsc::TryRecvError::Disconnected) => {
                                disconnected = true;
                                break;
                            }
                        }
                    }
                }
            }
            if disconnected {
                break;
            }

            let frame_data = self.prepare_frame();
            terminal.draw(|frame| {
                render(frame, &self.args, &self.hosts, &frame_data);
            })?;
        }
        Ok(())
    }
}

fn render(
    frame: &mut ratatui::Frame,
    args: &Args,
    hosts: &[Host],
    frame_data: &FrameData,
) {
    let size = frame.area();
    let area = Rect {
        x: args.horizontal_margin,
        y: args.vertical_margin,
        width: size
            .width
            .saturating_sub(args.horizontal_margin.saturating_mul(2)),
        height: size
            .height
            .saturating_sub(args.vertical_margin.saturating_mul(2)),
    };
    if area.width == 0 || area.height == 0 {
        return;
    }

    let host_count = hosts.len().max(1) as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(host_count), Constraint::Min(0)])
        .split(area);

    if !hosts.is_empty() {
        let header_constraints = vec![Constraint::Length(1); hosts.len()];
        let header_rows = Layout::default()
            .direction(Direction::Vertical)
            .constraints(header_constraints)
            .split(chunks[0]);
        for (index, host) in hosts.iter().enumerate() {
            let columns = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Percentage(30),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                ])
                .split(header_rows[index]);
            let mut cells: Vec<String> = vec![String::new(); 8];
            cells[0] = host.display_name.clone();
            if let Some(stats) = &frame_data.stats[index] {
                cells[1] = format!("last {}", format_duration(stats.last));
                cells[2] = format!("min {}", format_duration(stats.min));
                cells[3] = format!("max {}", format_duration(stats.max));
                cells[4] = format!("avg {}", format_duration(stats.avg));
                cells[5] = format!("jtr {}", format_duration(stats.jitter));
                cells[6] = format!("p95 {}", format_duration(stats.p95));
                cells[7] = format!("t/o {}", stats.timeouts);
            }
            for (cell_index, text) in cells.into_iter().enumerate() {
                let paragraph = Paragraph::new(Line::from(text))
                    .style(Style::default().fg(host.color));
                frame.render_widget(paragraph, columns[cell_index]);
            }
        }
    }

    let datasets: Vec<Dataset> = hosts
        .iter()
        .enumerate()
        .map(|(index, host)| {
            Dataset::default()
                .marker(if args.simple_graphics {
                    Marker::Dot
                } else {
                    Marker::Braille
                })
                .graph_type(GraphType::Line)
                .style(Style::default().fg(host.color))
                .data(&frame_data.datasets[index])
        })
        .collect();

    let chart = Chart::new(datasets)
        .x_axis(
            Axis::default()
                .style(Style::default().fg(Color::Gray))
                .bounds(frame_data.x_bounds)
                .labels(frame_data.x_labels.clone()),
        )
        .y_axis(
            Axis::default()
                .style(Style::default().fg(Color::Gray))
                .bounds(frame_data.y_bounds)
                .labels(frame_data.y_labels.clone()),
        );
    frame.render_widget(chart, chunks[1]);
}
