                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Percentage(30),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                    Constraint::Percentage(10),
                ])
                .split(header_rows[index]);
            let mut cells: Vec<String> = vec![String::new(); 8];
            cells[0] = host.display_name.clone();
            if let Some(stats) = &frame_data.stats[index] {
                cells[1] = format!("last {}", format_duration(stats.last));
                cells[2] = format!("min {}", format_duration(stats.min));
                cells[3] = format!("max {}", format_duration(stats.max));
                cells[4] = format!("avg {}", format_duration(stats.avg));
                cells[5] = format!("jtr {}", format_duration(stats.jitter));
                cells[6] = format!("p95 {}", format_duration(stats.p95));
                cells[7] = format!("t/o {}", stats.timeouts);
            }
            for (cell_index, text) in cells.into_iter().enumerate() {
                let paragraph = Paragraph::new(Line::from(text))
                    .style(Style::default().fg(host.color));
                frame.render_widget(paragraph, columns[cell_index]);
            }
        }
    }

    let datasets: Vec<Dataset> = hosts
        .iter()
        .enumerate()
        .map(|(index, host)| {
            Dataset::default()
                .marker(if args.simple_graphics {
                    Marker::Dot
                } else {
                    Marker::Braille
                })
                .graph_type(GraphType::Line)
                .style(Style::default().fg(host.color))
                .data(&frame_data.datasets[index])
        })
        .collect();

    let chart = Chart::new(datasets)
        .x_axis(
            Axis::default()
                .style(Style::default().fg(Color::Gray))
                .bounds(frame_data.x_bounds)
                .labels(frame_data.x_labels.clone()),
        )
        .y_axis(
            Axis::default()
                .style(Style::default().fg(Color::Gray))
                .bounds(frame_data.y_bounds)
                .labels(frame_data.y_labels.clone()),
        );
    frame.render_widget(chart, chunks[1]);
}
