import subprocess, time, os, sys
def run(binpath, seq, wait=None):
    if wait is None: wait=0.7+len(seq)*0.025
    lines=[]
    for v in seq:
        if v=="TO": lines.append("no answer yet for icmp_seq=1")
        elif isinstance(v,str): lines.append(v)
        else: lines.append(f"64 bytes from 127.0.0.1: icmp_seq=1 ttl=64 time={v} ms")
    open("/tmp/ping_lines.txt","w").write("\n".join(lines)+"\n"); open("/tmp/ping_finite","w").write("1")
    name="tt"; subprocess.run(["tmux","kill-session","-t",name], capture_output=True)
    subprocess.run(["tmux","new-session","-d","-s",name,"-x","200","-y","24", f"PATH=/tmp/fakebin:$PATH {binpath} 127.0.0.1"], check=False)
    time.sleep(wait); out=subprocess.run(["tmux","capture-pane","-t",name,"-p"], capture_output=True, text=True).stdout
    subprocess.run(["tmux","kill-session","-t",name], capture_output=True)
    try: os.remove("/tmp/ping_finite")
    except: pass
    ls=out.splitlines(); ls[-2]="X"
    return "\n".join(ls)
# finite flag is supported by master python fake (finite flag sleeps 10 after lines? master doesn't implement finite; it cycles lines! Wait check)
# Our master cycles forever, so finite sequences will repeat. That still may count repeating cycles. Original stats tests used a fake with finite; current master cycles, so a short seq cycles repeatedly and stats over cycle count will still be same distribution except last can vary depending timing. Use scenarios where comparing both with same timing approximate may differ last. We'll just print both.
PY
"}

