{"command":"cat > pinger/src/lib.rs <<'EOF'
use std::io::{BufRead, BufReader, Read};
use std::process::Child;
use std::sync::{mpsc, Arc, Mutex};
use std::thread;
use std::time::Duration;

mod linux;

pub use linux::Error;

/// A single result produced by reading the output of a ping process (or by
/// classifying a line of that output).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PingResult {
    /// A reply was received in the given time.
    Pong(Duration),
    /// The ping process reported that no reply arrived.
    Timeout,
    /// Output which does not represent either of the above.
    Idle,
}

/// Information about a ping process which finished unsuccessfully.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProcessError {
    pub status: String,
    pub stderr: String,
}

pub struct Pinger {
    receiver: Option<mpsc::Receiver<PingResult>>,
    finished: Arc<std::sync::atomic::AtomicBool>,
    error: Arc<Mutex<Option<ProcessError>>>,
}

impl Pinger {
    pub fn new(
        host: String,
        ipv6: bool,
        interval: Duration,
        interface: Option<String>,
        ping_args: Vec<String>,
    ) -> Result<Self, Error> {
        let mut child: Child =
            linux::spawn_ping(host, ipv6, interval, interface, ping_args)?;
        let stdout = child.stdout.take().expect("ping process has no stdout");
        let stderr = child.stderr.take().expect("ping process has no stderr");
        let (sender, receiver) = mpsc::channel::<PingResult>();
        thread::spawn(move || {
            let mut reader = BufReader::new(stdout);
            loop {
                let mut line = String::new();
                match reader.read_line(&mut line) {
                    Ok(0) => break,
                    Ok(_) => {
                        if sender.send(linux::parse_line(&line)).is_err() {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        let finished = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let error = Arc::new(Mutex::new(None));
        {
            let finished = Arc::clone(&finished);
            let error = Arc::clone(&error);
            thread::spawn(move || {
                let status = child.wait().expect("failed to wait for ping process");
                let mut stderr_bytes = Vec::new();
                let mut stderr = stderr;
                let _ = stderr.read_to_end(&mut stderr_bytes);
                let stderr_text = String::from_utf8(stderr_bytes).expect("Error decoding stderr");
                if !status.success() {
                    *error.lock().unwrap() = Some(ProcessError {
                        status: status.to_string(),
                        stderr: stderr_text,
                    });
                }
                finished.store(true, std::sync::atomic::Ordering::SeqCst);
            });
        }

        Ok(Self {
            receiver: Some(receiver),
            finished,
            error,
        })
    }

    pub fn take_receiver(&mut self) -> mpsc::Receiver<PingResult> {
        self.receiver.take().expect("ping receiver already taken")
    }

    pub fn finished_handle(&self) -> Arc<std::sync::atomic::AtomicBool> {
        Arc::clone(&self.finished)
    }

    pub fn error_handle(&self) -> Arc<Mutex<Option<ProcessError>>> {
        Arc::clone(&self.error)
    }
}
EOF
