        loop {""","""    ) -> Result<Option<pinger::ProcessError>, Failure> {
        let mut completion_error: Option<pinger::ProcessError> = None;
        loop {""")
old="""            let disconnected = self
                .hosts
                .iter()
                .any(|host| host.disconnected.load(std::sync::atomic::Ordering::SeqCst));
            if disconnected {
                break;
            }"""
new="""            let mut finished = false;
            for host in &self.hosts {
                if host.disconnected.load(std::sync::atomic::Ordering::SeqCst) {
                    finished = true;
                    if let Some(error_handle) = &host.ping_error {
                        completion_error = error_handle.lock().unwrap().clone();
                    }
                    break;
                }
            }
            if finished {
                break;
            }"""
