                render(frame, &self.args, &self.hosts, &frame_data);
            })?;
        }
        Ok(())
    }""","""            terminal.draw(|frame| {
                render(frame, &self.args, &self.hosts, &frame_data);
            })?;
        }
        Ok(completion_error)
    }""")
