import pathlib
p=pathlib.Path("gping/src/main.rs"); s=p.read_text()
start=s.index("    if !hosts.is_empty() {")
end=s.index("    // The chart implementation used by ratatui", start)
new='''    if !hosts.is_empty() {
        let rows: Vec<ratatui::widgets::Row> = hosts
            .iter()
            .enumerate()
            .map(|(index, host)| {
                let mut cells: Vec<ratatui::widgets::Cell> = Vec::new();
                cells.push(
                    ratatui::widgets::Cell::from(host.display_name.clone())
                        .style(Style::default().fg(host.color)),
                );
                if let Some(stats) = &frame_data.stats[index] {
                    for text in [
                        format!("last {}", format_duration(stats.last)),
                        format!("min {}", format_duration(stats.min)),
                        format!("max {}", format_duration(stats.max)),
                        format!("avg {}", format_duration(stats.avg)),
                        format!("jtr {}", format_duration(stats.jitter)),
                        format!("p95 {}", format_duration(stats.p95)),
                        format!("t/o {}", stats.timeouts),
                    ] {
                        cells.push(
                            ratatui::widgets::Cell::from(text)
                                .style(Style::default().fg(host.color)),
                        );
                    }
                }
                ratatui::widgets::Row::new(cells)
            })
            .collect();
        let table = ratatui::widgets::Table::new(
            rows,
            [
                Constraint::Percentage(30),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
            ],
        )
        .column_spacing(0);
        frame.render_widget(table, chunks[0]);
    }

'''
