import subprocess, itertools, os, time
tokens=["--cmd","-n","0.5","-b","30","-4","-6","-i","eth0","-s","--clear","-c","red","-c","blue,red","--ping-args","-x","127.0.0.1","localhost","--","-q","--help","-V","--version","--unknown","-h"]
# generate all combos up to length 3 from a smaller set plus some prebuilt sequences
cases=[[],["--cmd","echo"], ["127.0.0.1"]]
small=["--cmd","-4","-6","-s","--clear","127.0.0.1","localhost","-c","red","--ping-args","x"]
for r in range(1,4):
 for combo in itertools.permutations(small, r):
  # skip too many
  cases.append(list(combo))
